func (this *Lbank) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.SpotPublicGetWithdrawConfigs(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//    {
	//        "msg": "Success",
	//        "result": "true",
	//        "data": [
	//            {
	//                "amountScale": "4",
	//                "chain": "bep20(bsc)",
	//                "assetCode": "usdt",
	//                "min": "10",
	//                "transferAmtScale": "4",
	//                "canWithDraw": true,
	//                "fee": "0.0000",
	//                "minTransfer": "0.0001",
	//                "type": "1"
	//            },
	//            {
	//                "amountScale": "4",
	//                "chain": "trc20",
	//                "assetCode": "usdt",
	//                "min": "1",
	//                "transferAmtScale": "4",
	//                "canWithDraw": true,
	//                "fee": "1.0000",
	//                "minTransfer": "0.0001",
	//                "type": "1"
	//            },
	//            ...
	//        ],
	//        "error_code": "0",
	//        "ts": "1747973911431"
	//    }
	//
	var currenciesData []any = SafeListTyped(response, "data")
	var grouped map[string]any = this.GroupBy(currenciesData, "assetCode")
	var values []any = nil
	if grouped != nil {
		values = make([]any, 0, len(grouped))
		for _, objectValue := range grouped {
			values = append(values, objectValue)
		}
	}

	ch <- AsyncResult[map[string]any]{Value: this.ParseCurrencies(values)}
	return nil
}
func (this *Lbank) ParseCurrency(rawCurrency any) map[string]any {
	var id *string = this.SafeString(this.SafeDict(rawCurrency, 0, map[string]any{}), "assetCode") // first member is guaranteed
	var code *string = this.SafeCurrencyCode(id)
	var networks map[string]any = map[string]any{}
	for j := 0; j < GetArrayLength(rawCurrency); j++ {
		var networkEntry map[string]any = SafeMapTyped(rawCurrency, j)
		var networkId *string = this.SafeString(networkEntry, "chain")
		if networkId == nil {
			networkId = this.SafeString(networkEntry, "assetCode") // use type as fallback if networkId is not present
		}
		var networkCode *string = this.NetworkIdToCode(networkId, code)
		if networkCode != nil {
			networks[*networkCode] = map[string]any{
				"id":      networkId,
				"network": networkCode,
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": this.SafeNumber(networkEntry, "min"),
						"max": nil,
					},
					"deposit": map[string]any{
						"min": this.SafeNumber(networkEntry, "minTransfer"),
						"max": nil,
					},
				},
				"active":    nil,
				"deposit":   nil,
				"withdraw":  this.SafeBool(networkEntry, "canWithDraw"),
				"fee":       this.SafeNumber(networkEntry, "fee"),
				"precision": this.ParseNumber(this.ParsePrecision(this.SafeString(networkEntry, "transferAmtScale"))),
				"info":      networkEntry,
			}
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":        id,
		"code":      code,
		"precision": nil,
		"type":      nil,
		"name":      nil,
		"active":    nil,
		"deposit":   nil,
		"withdraw":  nil,
		"fee":       nil,
		"limits": map[string]any{
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": networks,
		"info":     rawCurrency,
	})
}

