func (this *Lbank) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	// spot: fetchTicker, fetchTickers
	//
	//     {
	//         "symbol": "btc_usdt",
	//         "ticker": {
	//             "high": "29695.57",
	//             "vol": "6890.2789",
	//             "low": "29110",
	//             "change": "0.58",
	//             "turnover": "202769821.06",
	//             "latest": "29405.98"
	//         },
	//         "timestamp": :1692064274908
	//     }
	//
	// swap: fetchTickers
	//
	//     {
	//         "lastTime": 1784884932,
	//         "prePositionFeeRate": "0.000053",
	//         "volume": "2435.459",
	//         "symbol": "BTCUSDT",
	//         "highestPrice": "29446.5",
	//         "lowestPrice": "29362.9",
	//         "openPrice": "29419.5",
	//         "markedPrice": "29385.1",
	//         "turnover": "36345526.2438402",
	//         "lastPrice": "29387.0"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(ticker, "timestamp")
	if timestamp == nil {
		timestamp = this.SafeTimestamp(ticker, "lastTime")
	}
	var marketId *string = this.SafeString(ticker, "symbol")
	var symbol *string = this.SafeSymbol(marketId, market)
	var tickerData map[string]any = this.SafeDictMap(ticker, "ticker", map[string]any{})
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var data any = func() any {
		if marketResolved["contract"] == true {
			return ticker
		}
		return tickerData
	}()
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString2(data, "high", "highestPrice"),
		"low":           this.SafeString2(data, "low", "lowestPrice"),
		"bid":           nil,
		"bidVolume":     nil,
		"ask":           nil,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          this.SafeString(data, "openPrice"),
		"close":         nil,
		"last":          this.SafeString2(data, "latest", "lastPrice"),
		"previousClose": nil,
		"change":        nil,
		"percentage":    this.SafeString(data, "change"),
		"average":       nil,
		"baseVolume":    this.SafeString2(data, "vol", "volume"),
		"quoteVolume":   this.SafeString(data, "turnover"),
		"info":          ticker,
	}, marketResolved)
}

