func (this *Lbank) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades (old) spotPublicGetTrades
	//
	//      {
	//          "date_ms":1647021989789,
	//          "amount":0.0028,
	//          "price":38804.2,
	//          "type":"buy",
	//          "tid":"52d5616ee35c43019edddebe59b3e094"
	//      }
	//
	//
	// fetchTrades (new) spotPublicGetTradesSupplement
	//
	//      {
	//          "quoteQty":1675.048485,
	//          "price":0.127545,
	//          "qty":13133,
	//          "id":"3589541dc22e4357b227283650f714e2",
	//          "time":1648058297110,
	//          "isBuyerMaker":false
	//      }
	//
	// fetchMyTrades (private)
	//
	//      {
	//          "orderUuid":"38b4e7a4-14f6-45fd-aba1-1a37024124a0",
	//          "tradeFeeRate":0.0010000000,
	//          "dealTime":1648500944496,
	//          "dealQuantity":30.00000000000000000000,
	//          "tradeFee":0.00453300000000000000,
	//          "txUuid":"11f3850cc6214ea3b495adad3a032794",
	//          "dealPrice":0.15111300000000000000,
	//          "dealVolumePrice":4.53339000000000000000,
	//          "tradeType":"sell_market"
	//      }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger2(trade, "date_ms", "time")
	if timestamp == nil {
		timestamp = this.SafeInteger(trade, "dealTime")
	}
	var amountString *string = this.SafeString2(trade, "amount", "qty")
	if amountString == nil {
		amountString = this.SafeString(trade, "dealQuantity")
	}
	var priceString *string = this.SafeString(trade, "price")
	if priceString == nil {
		priceString = this.SafeString(trade, "dealPrice")
	}
	var costString *string = this.SafeString(trade, "quoteQty")
	if costString == nil {
		costString = this.SafeString(trade, "dealVolumePrice")
	}
	var side *string = this.SafeString2(trade, "tradeType", "type")
	var typeVar *string = nil
	var takerOrMaker *string = nil
	if side != nil {
		var parts []string = strings.Split(*side, "_")
		side = this.SafeString(parts, 0)
		var typePart *string = this.SafeString(parts, 1)
		typeVar = SafeStringPtr("limit")
		takerOrMaker = SafeStringPtr("taker")
		if typePart != nil {
			if typePart != nil && *typePart == "market" {
				typeVar = SafeStringPtr("market")
			} else if typePart != nil && *typePart == "maker" {
				takerOrMaker = SafeStringPtr("maker")
			}
		}
	}
	var id *string = this.SafeString2(trade, "tid", "id")
	if id == nil {
		id = this.SafeString(trade, "txUuid")
	}
	var order *string = this.SafeString(trade, "orderUuid")
	var symbol *string = this.SafeSymbol(nil, market)
	var fee map[string]any = nil
	var feeCost *string = this.SafeString(trade, "tradeFee")
	if feeCost != nil {
		var feeCurr *string = func() *string {
			if side != nil && *side == "buy" {
				return this.SafeString(market, "base")
			}
			return this.SafeString(market, "quote")
		}()
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurr,
			"rate":     this.SafeString(trade, "tradeFeeRate"),
		}
	}
	return this.SafeTrade(map[string]any{
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"id":           id,
		"order":        order,
		"type":         typeVar,
		"takerOrMaker": takerOrMaker,
		"side":         side,
		"price":        priceString,
		"amount":       amountString,
		"cost":         costString,
		"fee":          fee,
		"info":         trade,
	}, market)
}

