	//               }
	//           ],
	//           "error_code":0,
	//           "ts":1647021999308
	//      }
	//
	var trades []any = SafeListTypedDefault(response, "data", []any{})

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(trades, market, since, limit))}
