func (this *Lbank) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// endpoint doesnt work
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var limitResolved int64 = this.ParseToInt(func() any {
		if limit == nil {
			return 100
		}
		return mathMin(limit, 2000)
	}())
	var duration int64 = this.ParseTimeframe(timeframe)
	var now int64 = this.Milliseconds()
	var defaultSince int64 = now - ((duration * 1000) * limitResolved)
	var sinceResolved any = defaultSince
	var parsedSince int64 = this.ParseToInt(float64(defaultSince) / 1000)
	if since != nil {
		sinceResolved = since
		parsedSince = this.ParseToInt(float64(*since) / 1000)
	}
	var parsedLimit any = mathMin(limitResolved+1, 2000) // max 2000;
	var request map[string]any = map[string]any{
		"symbol": market["id"],
		"type":   this.SafeString(this.Timeframes, timeframe, timeframe),
		"time":   parsedSince,
		"size":   parsedLimit,
	}

	r1 := <-this.SpotPublicGetKline(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var ohlcvs []any = SafeListTypedDefault(response, "data", []any{})

	//
	//
	// [
	//   [
	//     1482311500,
	//     5423.23,
	//     5472.80,
	//     5516.09,
	//     5462,
	//     234.3250
	//   ],
	//   [
	//     1482311400,
	//     5432.52,
	//     5459.87,
	//     5414.30,
	//     5428.23,
	//     213.7329
	//   ]
	// ]
	//
	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(ohlcvs, market, timeframe, sinceResolved, limitResolved))}
	return nil
}
func (this *Lbank) ParseBalance(response any) map[string]any {
	//
	// spotPrivatePostUserInfo
	//
	//      {
	//          "toBtc": {
	//              "egc:": "0",
	//              "iog": "0",
	//              "ksm": "0",
	//              },
	//          "freeze": {
	//              "egc": "0",
	//              "iog": "0",
	//              "ksm": "0" ,
	//              },
	//          "asset": {
	//              "egc": "0",
	//              "iog": "0",
	//              "ksm": "0",
	//              },
	//          "free": {
	//              "egc": "0",
	//              "iog": "0",
	//              "ksm": "0",
	//              }
	//      }
	//
	// spotPrivatePostSupplementUserInfoAccount
	//
	//      {
	//          "balances":[
	//              {
	//                  "asset":"lbk",
	//                  "free":"0",
	//                  "locked":"0"
	//              }, ...
	//          ]
	//      }
	//
	// spotPrivatePostSupplementUserInfo
	//
	//      [
	//          {
	//              "usableAmt":"31.45130723",
	//              "assetAmt":"31.45130723",
	//              "networkList":[
	//                  {
	//                      "isDefault":true,
	//                      "withdrawFeeRate":"",
	//                      "name":"bep20(bsc)",
	//                      "withdrawMin":30,
	//                      "minLimit":0.0001,
	//                      "minDeposit":0.0001,
	//                      "feeAssetCode":"doge",
	//                      "withdrawFee":"30",
	//                      "type":1,
	//                      "coin":"doge",
	//                      "network":"bsc"
	//                  },
	//                  {
	//                      "isDefault":false,
	//                      "withdrawFeeRate":"",
	//                      "name":"dogecoin",
	//                      "withdrawMin":10,
	//                      "minLimit":0.0001,
	//                      "minDeposit":10,
	//                      "feeAssetCode":"doge",
	//                      "withdrawFee":"10",
	//                      "type":1,
	//                      "coin":"doge",
	//                      "network":"dogecoin"
	//                  }
	//              ],
	//              "freezeAmt":"0",
	//              "coin":"doge"
	//          }, ...
	//      ]
	//
	var timestamp *int64 = this.SafeInteger(response, "ts")
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
	var data any = this.SafeDict(response, "data")
	// from spotPrivatePostUserInfo
	var toBtc map[string]any = SafeMapTyped(data, "toBtc")
	if toBtc != nil {
		var used map[string]any = SafeMapTyped(data, "freeze")
		var free map[string]any = SafeMapTyped(data, "free")
		var currencies []string = nil
		if free != nil {
			currencies = make([]string, 0, len(free))
			for objectKey := range free {
				currencies = append(currencies, objectKey)
			}
		}
		for i := 0; i < len(currencies); i++ {
			var currencyId string = currencies[i]
			var code *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["used"] = this.SafeString(used, currencyId)
			account["free"] = this.SafeString(free, currencyId)
			if code != nil {
				result[*code] = account
			}
		}
		return this.SafeBalance(result).(map[string]any)
	}
	// from spotPrivatePostSupplementUserInfoAccount
	var balances []any = SafeListTyped(data, "balances")
	if balances != nil {
		for i := 0; i < len(balances); i++ {
			var item map[string]any = SafeMapTyped(balances, i)
			var currencyId *string = this.SafeString(item, "asset")
			var codeInner *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["free"] = this.SafeString(item, "free")
			account["used"] = this.SafeString(item, "locked")
			if codeInner != nil {
				result[*codeInner] = account
			}
		}
		return this.SafeBalance(result).(map[string]any)
	}
	// from spotPrivatePostSupplementUserInfo
	var isArray bool = false
	if isArray {
		for i := 0; i < GetArrayLength(data); i++ {
			var item map[string]any = SafeMapTyped(data, i)
			var currencyId *string = this.SafeString(item, "coin")
			var codeInner *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["free"] = this.SafeString(item, "usableAmt")
			account["used"] = this.SafeString(item, "freezeAmt")
			if codeInner != nil {
				result[*codeInner] = account
			}
		}
		return this.SafeBalance(result).(map[string]any)
	}
	return this.SafeBalance(result).(map[string]any)
}
func (this *Lbank) ParseFundingRate(ticker any, optionalArgs ...any) FundingRate {
	// {
	//     "symbol": "BTCUSDT",
	//     "highestPrice": "69495.5",
	//     "underlyingPrice": "68455.904",
	//     "lowestPrice": "68182.1",
	//     "openPrice": "68762.4",
	//     "positionFeeRate": "0.0001",
	//     "volume": "33534.2858",
	//     "markedPrice": "68434.1",
	//     "turnover": "1200636218.210558",
	//     "positionFeeTime": "28800",
	//     "lastPrice": "68427.3",
	//     "nextFeeTime": "1730736000000",
	//     "fundingRate": "0.0001",
	// }
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "symbol")
	var symbol *string = this.SafeSymbol(marketId, market)
	var markPrice *float64 = this.SafeNumber(ticker, "markedPrice")
	var indexPrice *float64 = this.SafeNumber(ticker, "underlyingPrice")
	var fundingRate *float64 = this.SafeNumber(ticker, "fundingRate")
	var fundingTime *int64 = this.SafeInteger(ticker, "nextFeeTime")
	var positionFeeTime *int64 = this.SafeInteger(ticker, "positionFeeTime")
	var intervalString *string = nil
	if positionFeeTime != nil {
		var interval int64 = this.ParseToInt((float64(*positionFeeTime) / 60) / 60)
		intervalString = SafeStringPtr(strconv.FormatInt(interval, 10) + "h")
	}
	return FundingRateFromMap(map[string]any{
		"info":                     ticker,
		"symbol":                   symbol,
		"markPrice":                markPrice,
		"indexPrice":               indexPrice,
		"fundingRate":              fundingRate,
		"fundingTimestamp":         fundingTime,
		"fundingDatetime":          this.Iso8601(fundingTime),
		"timestamp":                nil,
		"datetime":                 nil,
		"nextFundingRate":          nil,
		"nextFundingTimestamp":     nil,
		"nextFundingDatetime":      nil,
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
		"interval":                 intervalString,
	})
}

